lcui-app.resource:
.spinner-size-demo {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 16px;
}
.spinner-size-demo .sz-sm {
    width: 24px;
    height: 24px;
}
.spinner-size-demo .sz-md {
    width: 40px;
    height: 40px;
}
.spinner-size-demo .sz-lg {
    width: 64px;
    height: 64px;
}
